package com.hookdeveloper.catlive.remote;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
public class RemoteTimerTest {
 JSONObject command(String id,String action,int value)throws Exception{return new JSONObject().put("id",id).put("action",action).put("value",value);}
 JSONObject snapshot(String revision,String command,boolean running,double remaining)throws Exception{return new JSONObject().put("revision",revision).put("commandID",command).put("running",running).put("remainingSeconds",remaining);}
 @Test public void startAndStopRespondBeforeHostAndIgnoreEarlierCommand()throws Exception{RemoteTimer t=new RemoteTimer();t.receive(snapshot("a","",false,0),0);t.command(command("start","timerStart",60),100);assertTrue(t.running);assertEquals(59,t.value(1100),0);t.command(command("stop","timerStop",0),1200);assertFalse(t.running);t.receive(snapshot("b","start",true,58),1300);assertFalse(t.running);t.receive(snapshot("c","stop",false,0),1400);assertFalse(t.running);assertTrue(t.pending.isEmpty());}
 @Test public void missingAcknowledgementReconcilesAfterDeadline()throws Exception{RemoteTimer t=new RemoteTimer();t.command(command("start","timerStart",60),100);t.receive(snapshot("a","",false,0),3000);assertTrue(t.running);t.receive(snapshot("a","",false,0),3101);assertFalse(t.running);}
 @Test public void repeatedSnapshotDoesNotRestartCountdownAndNewProjectClearsPending()throws Exception{RemoteTimer t=new RemoteTimer();t.scope("P");JSONObject s=snapshot("a","",true,60);t.receive(s,0);t.receive(s,1000);assertEquals(59,t.value(1000),0);t.command(command("start","timerStart",90),1100);t.scope("Q");assertTrue(t.pending.isEmpty());assertFalse(t.running);}
 @Test public void targetIsRememberedAcrossStopAndSnapshots()throws Exception{RemoteTimer t=new RemoteTimer();t.command(command("start","timerStart",3723),100);long run=t.runID;t.command(command("stop","timerStop",0),200);assertEquals(3723,t.targetSeconds);assertNotEquals(run,t.runID);t.receive(snapshot("a","stop",false,0).put("targetSeconds",3723),300);assertEquals(3723,t.targetSeconds);assertEquals("00:00:00",RemoteTimer.formatted(t.value(400)));}
 @Test public void displayUsesIOSCeilingAndUnicodeMinus(){assertEquals("00:00:01",RemoteTimer.formatted(.1));assertEquals("00:00:00",RemoteTimer.formatted(-.1));assertEquals("−00:00:01",RemoteTimer.formatted(-1.1));assertEquals("01:02:03",RemoteTimer.formatted(3723));}
}
